<template>
  <div class="item-data-container">
    <div class="section-search">
      <v-text-field
          class="first-input input"
          :class="{'active-input': !isCompareInput}"
          v-model="mainItemInput"
          label="Искать товар"
          color="teal"
          density="compact"
          variant="underlined"
          hide-details="auto"
          clearable>
      </v-text-field>
      <v-text-field
          class="second-input input"
          :class="{'active-input-second': !isCompareInput}"
          v-model="compareItemInput"
          label="Сравнить товар"
          color="teal"
          density="compact"
          variant="underlined"
          hide-details="auto"
          :disabled="isCompareInput"
          clearable>
      </v-text-field>
      <v-btn
          size="small"
          color="teal"
          class="controls_btn"
          :disabled="isDisabled"
          @click="processingRequest"
      >
        Поиск
      </v-btn>
    </div>

    <div class="section-chart-data" v-if="firstElementTitle">
      <div class="section-item-wrapper">
        <div class="item-title">{{ firstElementTitle }}</div>
        <div class="section-item-info">
          <div class="item-info-left">
            <img alt="photo" :src="firstElementImg">
          </div>
          <div class="item-info-right">
            <div class="item-code">
              <div class="data">Код товара</div>
              <div class="info">{{ firstElementCode }}</div>
            </div>
            <div class="item-erticle-tnp">
              <div class="data">Артикул ТНП</div>
              <div class="info">{{ firstElementArtTnp }}</div>
            </div>
            <div class="item-erticle-epc">
              <div class="data">Артикул ЕПЦ</div>
              <div class="info">{{ firstElementArtEpc }}</div>
            </div>
            <div class="item-category">
              <div class="data">Категория</div>
              <div class="info">{{ firstElementCategory }}</div>
            </div>
          </div>
        </div>
        <div class="section-table">
          <table>
            <caption>Данные продаж по годам</caption>
            <thead>
            <tr>
              <th colspan="2">2023</th>
              <th colspan="2">2024</th>
              <th colspan="2">2025</th>
            </tr>
            <tr>
              <th>шт</th>
              <th>грн</th>
              <th>шт</th>
              <th>грн</th>
              <th>шт</th>
              <th>грн</th>
            </tr>
            </thead>
            <tbody>
            <tr>
              <td class="sales-count-23">{{ firstElement2023Count }}</td>
              <td class="sales-money-23">{{ firstElement2023Money }}</td>
              <td class="sales-count-24">{{ firstElement2024Count }}</td>
              <td class="sales-money-24">{{ firstElement2024Money }}</td>
              <td class="sales-count-25">{{ firstElement2025Count }}</td>
              <td class="sales-money-25">{{ firstElement2025Money }}</td>
            </tr>
            </tbody>
          </table>
        </div>
      </div>
      <div class="section-chart">
        <div class="chart">
          <canvas ref="itemChart" class="item-chart"></canvas>
        </div>
        <div class="chart-controls">
          <v-btn
              size="small"
              color="teal"
              class="controls_btn controls_btn_left"
              :disabled="isDisabled"
              @click="renderChartAllSingle"
          >
            Все данные
          </v-btn>
          <v-btn
              size="small"
              color="#2196F3"
              class="controls_btn"
              :disabled="isDisabled"
              @click="renderChart2023AndRest"
          >
            2023
          </v-btn>
          <v-btn
              size="small"
              color="#FF4081"
              class="controls_btn"
              :disabled="isDisabled"
              @click="renderChart2024AndRest"
          >
            2024
          </v-btn>
          <v-btn
              size="small"
              color="#FB8C00"
              class="controls_btn"
              :disabled="isDisabled"
              @click="renderChart2025AndRest"
          >
            2025
          </v-btn>
        </div>
      </div>
    </div>
    <div class="section-divider" v-if="firstElementTitleCompare"></div>
    <div class="section-chart-data" v-if="firstElementTitleCompare">
      <div class="section-item-wrapper">
        <div class="item-title">{{ firstElementTitleCompare }}</div>
        <div class="section-item-info">
          <div class="item-info-left">
            <img alt="photo" :src="firstElementImgCompare">
          </div>
          <div class="item-info-right">
            <div class="item-code">
              <div class="data">Код товара</div>
              <div class="info">{{ firstElementCodeCompare }}</div>
            </div>
            <div class="item-erticle-tnp">
              <div class="data">Артикул ТНП</div>
              <div class="info">{{ firstElementArtTnpCompare }}</div>
            </div>
            <div class="item-erticle-epc">
              <div class="data">Артикул ЕПЦ</div>
              <div class="info">{{ firstElementArtEpcCompare }}</div>
            </div>
            <div class="item-category">
              <div class="data">Категория</div>
              <div class="info">{{ firstElementCategoryCompare }}</div>
            </div>
          </div>
        </div>
        <div class="section-table">
          <table>
            <caption>Данные продаж по годам</caption>
            <thead>
            <tr>
              <th colspan="2">2023</th>
              <th colspan="2">2024</th>
              <th colspan="2">2025</th>
            </tr>
            <tr>
              <th>шт</th>
              <th>грн</th>
              <th>шт</th>
              <th>грн</th>
              <th>шт</th>
              <th>грн</th>
            </tr>
            </thead>
            <tbody>
            <tr>
              <td class="sales-count-23">{{ firstElement2023CountCompare }}</td>
              <td class="sales-money-23">{{ firstElement2023MoneyCompare }}</td>
              <td class="sales-count-24">{{ firstElement2024CountCompare }}</td>
              <td class="sales-money-24">{{ firstElement2024MoneyCompare }}</td>
              <td class="sales-count-25">{{ firstElement2025CountCompare }}</td>
              <td class="sales-money-25">{{ firstElement2025MoneyCompare }}</td>
            </tr>
            </tbody>
          </table>
        </div>
      </div>
      <div class="section-chart">
        <div class="chart">
          <canvas ref="itemChartCompare" class="item-chart"></canvas>
        </div>
        <div class="chart-controls">
          <v-btn
              size="small"
              color="teal"
              class="controls_btn controls_btn_left"
              :disabled="isDisabled"
              @click="renderChartAllSingleCompare"
          >
            Все данные
          </v-btn>
          <v-btn
              size="small"
              color="#2196F3"
              class="controls_btn"
              :disabled="isDisabled"
              @click="renderChart2023AndRestCompare"
          >
            2023
          </v-btn>
          <v-btn
              size="small"
              color="#FF4081"
              class="controls_btn"
              :disabled="isDisabled"
              @click="renderChart2024AndRestCompare"
          >
            2024
          </v-btn>
          <v-btn
              size="small"
              color="#FB8C00"
              class="controls_btn"
              :disabled="isDisabled"
              @click="renderChart2025AndRestCompare"
          >
            2025
          </v-btn>
        </div>
      </div>
    </div>

  </div>
  <v-snackbar
      v-model="snackbar"
      timeout="2000"
  >
    {{ snackbarText }}

    <template v-slot:actions>
      <v-btn
          color="red"
          variant="text"
          @click="snackbar = false"
      >
        Close
      </v-btn>
    </template>
  </v-snackbar>
</template>

<script>

import {DataStorage} from "@/functions/data-storage";
import {Chart} from "chart.js";

export default {
  name: "ItemSalesData",
  data() {
    return {
      isDisabled: false,
      isCompareInput: true,
      mainItemInput: null,
      compareItemInput: null,
      isRenderingChart: false,
      isRenderingChartCompare: false,

      storage: DataStorage,
      fullSales: [],
      nameOfMonth: [],
      // Данные для заполнения таблицы ----------
      firstElementTitle: null,
      firstElementCode: null,
      firstElementArtTnp: null,
      firstElementArtEpc: null,
      firstElementCategory: null,
      firstElementImg: null,
      firstElement2023Count: '-',
      firstElement2023Money: '-',
      firstElement2024Count: '-',
      firstElement2024Money: '-',
      firstElement2025Count: '-',
      firstElement2025Money: '-',

      // Данные для графика single-елемента ----------
      currentFindElement: null,

      single2023Count: null,
      single2023Rest: null,
      single2024Count: null,
      single2024Rest: null,
      single2025Count: null,
      single2025Rest: null,

      // Данные для заполнения таблицы Compare ----------
      firstElementTitleCompare: null,
      firstElementCodeCompare: null,
      firstElementArtTnpCompare: null,
      firstElementArtEpcCompare: null,
      firstElementCategoryCompare: null,
      firstElementImgCompare: null,
      firstElement2023CountCompare: '-',
      firstElement2023MoneyCompare: '-',
      firstElement2024CountCompare: '-',
      firstElement2024MoneyCompare: '-',
      firstElement2025CountCompare: '-',
      firstElement2025MoneyCompare: '-',

      // Данные для графика single-елемента Compare----------
      currentFindElementCompare: null,

      single2023CountCompare: null,
      single2023RestCompare: null,
      single2024CountCompare: null,
      single2024RestCompare: null,
      single2025CountCompare: null,
      single2025RestCompare: null,

      snackbar: false,
      snackbarText: 'test',
    };
  },
  methods: {
    injectData() {
      this.fullSales = [...this.storage.prototype.fullData];
      this.nameOfMonth = [...this.storage.prototype.monthNames];
    },
    destroyChart() {
      if (this.chart) {
        this.chart.destroy();
        this.chart = null;
      }
    },
    destroyChartCompare() {
      if (this.chartCompare) {
        this.chartCompare.destroy();
        this.chartCompare = null;
      }
    },
    showSnackBar(message) {
      this.snackbarText = message;
      this.snackbar = true;
    },
    handleEnter(event) {
      if (event.key === 'Enter') {
        this.processingRequest();
      }
    },
    getPhotoPath(article) {
      try {
        return require(`@/assets/images/${article}.webp`);
      } catch (error) {
        try {
          const modifiedArticle = article.replaceAll('/', '-');
          return require(`@/assets/images/${modifiedArticle}.webp`);
        } catch (error) {
          // console.error(Image not found: ${article}.webp);
          return require('@/assets/images/error.webp');
        }
      }
    },

    processingRequest() {
      if ((this.mainItemInput !== null && this.mainItemInput.trim() !== '') &&
          (this.compareItemInput === null || this.compareItemInput.trim() === '')) {
        this.chooseSearchType(this.mainItemInput);
      } else if (this.mainItemInput && this.compareItemInput) {
        if (this.mainItemInput.trim() !== '' && this.compareItemInput.trim() !== '') {
          this.compareItems(this.mainItemInput.trim(), this.compareItemInput.trim())
        } else {
          this.showSnackBar('Введите корректные данные!');
        }
      } else {
        this.showSnackBar('Введите данные!');
      }
    },
    chooseSearchType(data) {
      let search = null;
      if (data.includes(',')) {
        search = this.transformStringToArr(data);
        if (search.length < 1) {
          this.showSnackBar('Введите корректные данные!');
        } else if (search.length > 0 && search.length < 2) {
          this.singleSearch(search[0]);
        } else {
          this.multipleSearch(search);
        }
      } else {
        search = data.trim();
        this.singleSearch(search);
      }
    },
    transformStringToArr(data) {
      let tempArr = data.split(',');
      let finalArr = [];
      for (let i = 0; i < tempArr.length; i++) {
        if (tempArr[i].trim() !== '') {
          finalArr.push(tempArr[i].trim())
        }
      }
      return finalArr;
    },

    multipleSearch(elements) {
      console.log(elements);
    },
    compareItems(inputMain, inputCompare) {
      if (!inputMain.includes(',') && !inputCompare.includes(',')) {
        this.singleSearch(inputMain);
        this.singleSearchCompare(inputCompare);
      }
    },

    // Single
    singleSearch(element) {
      this.currentFindElement = element;

      let result = null;
      result = this.fullSales.filter(f => f.article_tnp === element);
      if (result.length < 1) {
        result = this.fullSales.filter(f => f.article_epc === element);
        if (result.length < 1) {
          result = this.fullSales.filter(f => f.code === element);
          if (result.length < 1) {
            this.showSnackBar('Товар не найден!')
            return
          }
        }
      }
      this.firstElementImg = this.getPhotoPath(result[0].article_tnp);
      this.firstElementTitle = result[0].title;
      this.firstElementCode = result[0].code;
      this.firstElementArtTnp = result[0].article_tnp;
      this.firstElementArtEpc = result[0].article_epc;
      this.firstElementCategory = result[0].category;

      let data2023 = result.filter(e => e.year === '2023');
      let data2024 = result.filter(e => e.year === '2024');
      let data2025 = result.filter(e => e.year === '2025');

      this.firstElement2023Count = data2023.reduce((acc, item) => acc + item.count, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2023Money = data2023.reduce((acc, item) => acc + item.money, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2024Count = data2024.reduce((acc, item) => acc + item.count, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2024Money = data2024.reduce((acc, item) => acc + item.money, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2025Count = data2025.reduce((acc, item) => acc + item.count, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2025Money = data2025.reduce((acc, item) => acc + item.money, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});

      let year2023 = [];
      let year2024 = [];
      let year2025 = [];

      this.nameOfMonth.map(month => {
        const filteredArr = data2023.filter(item => item.month === month);
        const countSum = filteredArr.reduce((acc, item) => acc + item.count, 0);
        const restSum = filteredArr.reduce((acc, item) => acc + item.rest, 0);
        const moneySum = filteredArr.reduce((acc, item) => acc + item.money, 0);

        year2023.push({
          month: month,
          count: countSum === 0 ? null : Number(countSum.toFixed(0)),
          rest: restSum === 0 ? null : Number(restSum.toFixed(0)),
          money: moneySum === 0 ? null : Number(moneySum.toFixed(0))
        });
      });
      this.nameOfMonth.map(month => {
        const filteredArr = data2024.filter(item => item.month === month);
        const countSum = filteredArr.reduce((acc, item) => acc + item.count, 0);
        const restSum = filteredArr.reduce((acc, item) => acc + item.rest, 0);
        const moneySum = filteredArr.reduce((acc, item) => acc + item.money, 0);

        year2024.push({
          month: month,
          count: countSum === 0 ? null : Number(countSum.toFixed(0)),
          rest: restSum === 0 ? null : Number(restSum.toFixed(0)),
          money: moneySum === 0 ? null : Number(moneySum.toFixed(0))
        });
      });
      this.nameOfMonth.map(month => {
        const filteredArr = data2025.filter(item => item.month === month);
        const countSum = filteredArr.reduce((acc, item) => acc + item.count, 0);
        const restSum = filteredArr.reduce((acc, item) => acc + item.rest, 0);
        const moneySum = filteredArr.reduce((acc, item) => acc + item.money, 0);

        year2025.push({
          month: month,
          count: countSum === 0 ? null : Number(countSum.toFixed(0)),
          rest: restSum === 0 ? null : Number(restSum.toFixed(0)),
          money: moneySum === 0 ? null : Number(moneySum.toFixed(0))
        });
      });

      this.single2023Count = year2023.map(item => item.count);
      this.single2023Rest = year2023.map(item => item.rest);
      this.single2024Count = year2024.map(item => item.count);
      this.single2024Rest = year2024.map(item => item.rest);
      this.single2025Count = year2025.map(item => item.count);
      this.single2025Rest = year2025.map(item => item.rest);

      this.renderChartAllSingle();
    },
    renderChartAllSingle(){
      let message = `Динамика продаж ${this.currentFindElement} в Епицентре в разрезе 2023, 2024, 2025 гг.`
      let datasetArr = [
        {
          label: '2023',
          data: this.single2023Count,
          borderColor: '#2196F3',
          backgroundColor: 'rgba(33,150,243,0.4)', // прозрачный фон
          pointBackgroundColor: '#2196F3',
          tension: 0.3
        },
        {
          label: '2024',
          data: this.single2024Count,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: '2025',
          data: this.single2025Count,
          borderColor: '#FF9100',
          backgroundColor: 'rgba(255,145,0,0.4)',
          pointBackgroundColor: '#FF9100',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesData(datasetArr, message);
    },
    renderChart2023AndRest(){
      let message = `Сравнение продаж с остатками '${this.currentFindElement}' в Епицентре за 2023 год.`
      let datasetArr = [
        {
          label: 'Продажи',
          data: this.single2023Count,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: 'Остатки',
          data: this.single2023Rest,
          borderColor: '#4CAF50',
          backgroundColor: 'rgba(76,175,80,0.4)',
          pointBackgroundColor: '#4CAF50',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesData(datasetArr, message);
    },
    renderChart2024AndRest(){
      let message = `Сравнение продаж с остатками '${this.currentFindElement}' в Епицентре за 2024 год.`
      let datasetArr = [
        {
          label: 'Продажи',
          data: this.single2024Count,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: 'Остатки',
          data: this.single2024Rest,
          borderColor: '#4CAF50',
          backgroundColor: 'rgba(76,175,80,0.4)',
          pointBackgroundColor: '#4CAF50',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesData(datasetArr, message);
    },
    renderChart2025AndRest(){
      let message = `Сравнение продаж с остатками '${this.currentFindElement}' в Епицентре за 2025 год.`
      let datasetArr = [
        {
          label: 'Продажи',
          data: this.single2025Count,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: 'Остатки',
          data: this.single2025Rest,
          borderColor: '#4CAF50',
          backgroundColor: 'rgba(76,175,80,0.4)',
          pointBackgroundColor: '#4CAF50',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesData(datasetArr, message);
    },

    showSingleElementSalesData(data, msg) {
      let datasets = data;

      if (this.isRenderingChart) return;
      this.isRenderingChart = true;

      this.destroyChart();

      this.$nextTick(() => {
        this.createChartLine(this.nameOfMonth, datasets, msg);

        setTimeout(() => {
          this.isRenderingChart = false;
          this.isDisabled = false;
        }, 1000);
      });
    },
    createChartLine(months, data, message) {
      let title = message;
      const canvas = this.$refs.itemChart;
      if (!canvas) {
        console.warn('Canvas не найден');
        return;
      }
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        console.warn('Контекст canvas не получен');
        return;
      }

      this.chart = new Chart(ctx, {
        type: 'line',
        data: {
          labels: months,
          datasets: data
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              position: 'top',
            },
            title: {
              display: true,
              text: title
            },
            datalabels: {
              display: false // ⛔️ отключает подписи данных
            }
          }
        },
      });
    },

    // Compare
    singleSearchCompare(element) {
      this.currentFindElementCompare = element;

      let result = null;
      result = this.fullSales.filter(f => f.article_tnp === element);
      if (result.length < 1) {
        result = this.fullSales.filter(f => f.article_epc === element);
        if (result.length < 1) {
          result = this.fullSales.filter(f => f.code === element);
          if (result.length < 1) {
            this.showSnackBar('Товар не найден!')
            return
          }
        }
      }
      this.firstElementImgCompare = this.getPhotoPath(result[0].article_tnp);
      this.firstElementTitleCompare = result[0].title;
      this.firstElementCodeCompare = result[0].code;
      this.firstElementArtTnpCompare = result[0].article_tnp;
      this.firstElementArtEpcCompare = result[0].article_epc;
      this.firstElementCategoryCompare = result[0].category;

      let data2023 = result.filter(e => e.year === '2023');
      let data2024 = result.filter(e => e.year === '2024');
      let data2025 = result.filter(e => e.year === '2025');

      this.firstElement2023CountCompare = data2023.reduce((acc, item) => acc + item.count, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2023MoneyCompare = data2023.reduce((acc, item) => acc + item.money, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2024CountCompare = data2024.reduce((acc, item) => acc + item.count, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2024MoneyCompare = data2024.reduce((acc, item) => acc + item.money, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2025CountCompare = data2025.reduce((acc, item) => acc + item.count, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});
      this.firstElement2025MoneyCompare = data2025.reduce((acc, item) => acc + item.money, 0)
          .toLocaleString('uk-UA', {minimumFractionDigits: 0, maximumFractionDigits: 0});

      let year2023 = [];
      let year2024 = [];
      let year2025 = [];

      this.nameOfMonth.map(month => {
        const filteredArr = data2023.filter(item => item.month === month);
        const countSum = filteredArr.reduce((acc, item) => acc + item.count, 0);
        const restSum = filteredArr.reduce((acc, item) => acc + item.rest, 0);
        const moneySum = filteredArr.reduce((acc, item) => acc + item.money, 0);

        year2023.push({
          month: month,
          count: countSum === 0 ? null : Number(countSum.toFixed(0)),
          rest: restSum === 0 ? null : Number(restSum.toFixed(0)),
          money: moneySum === 0 ? null : Number(moneySum.toFixed(0))
        });
      });
      this.nameOfMonth.map(month => {
        const filteredArr = data2024.filter(item => item.month === month);
        const countSum = filteredArr.reduce((acc, item) => acc + item.count, 0);
        const restSum = filteredArr.reduce((acc, item) => acc + item.rest, 0);
        const moneySum = filteredArr.reduce((acc, item) => acc + item.money, 0);

        year2024.push({
          month: month,
          count: countSum === 0 ? null : Number(countSum.toFixed(0)),
          rest: restSum === 0 ? null : Number(restSum.toFixed(0)),
          money: moneySum === 0 ? null : Number(moneySum.toFixed(0))
        });
      });
      this.nameOfMonth.map(month => {
        const filteredArr = data2025.filter(item => item.month === month);
        const countSum = filteredArr.reduce((acc, item) => acc + item.count, 0);
        const restSum = filteredArr.reduce((acc, item) => acc + item.rest, 0);
        const moneySum = filteredArr.reduce((acc, item) => acc + item.money, 0);

        year2025.push({
          month: month,
          count: countSum === 0 ? null : Number(countSum.toFixed(0)),
          rest: restSum === 0 ? null : Number(restSum.toFixed(0)),
          money: moneySum === 0 ? null : Number(moneySum.toFixed(0))
        });
      });

      this.single2023CountCompare = year2023.map(item => item.count);
      this.single2023RestCompare = year2023.map(item => item.rest);
      this.single2024CountCompare = year2024.map(item => item.count);
      this.single2024RestCompare = year2024.map(item => item.rest);
      this.single2025CountCompare = year2025.map(item => item.count);
      this.single2025RestCompare = year2025.map(item => item.rest);

      this.renderChartAllSingleCompare();
    },
    renderChartAllSingleCompare(){
      let message = `Динамика продаж ${this.currentFindElementCompare} в Епицентре в разрезе 2023, 2024, 2025 гг.`
      let datasetArr = [
        {
          label: '2023',
          data: this.single2023CountCompare,
          borderColor: '#2196F3',
          backgroundColor: 'rgba(33,150,243,0.4)', // прозрачный фон
          pointBackgroundColor: '#2196F3',
          tension: 0.3
        },
        {
          label: '2024',
          data: this.single2024CountCompare,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: '2025',
          data: this.single2025CountCompare,
          borderColor: '#FF9100',
          backgroundColor: 'rgba(255,145,0,0.4)',
          pointBackgroundColor: '#FF9100',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesDataCompare(datasetArr, message);
    },
    renderChart2023AndRestCompare(){
      let message = `Сравнение продаж с остатками '${this.currentFindElementCompare}' в Епицентре за 2023 год.`
      let datasetArr = [
        {
          label: 'Продажи',
          data: this.single2023CountCompare,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: 'Остатки',
          data: this.single2023RestCompare,
          borderColor: '#4CAF50',
          backgroundColor: 'rgba(76,175,80,0.4)',
          pointBackgroundColor: '#4CAF50',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesDataCompare(datasetArr, message);
    },
    renderChart2024AndRestCompare(){
      let message = `Сравнение продаж с остатками '${this.currentFindElementCompare}' в Епицентре за 2024 год.`
      let datasetArr = [
        {
          label: 'Продажи',
          data: this.single2024CountCompare,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: 'Остатки',
          data: this.single2024RestCompare,
          borderColor: '#4CAF50',
          backgroundColor: 'rgba(76,175,80,0.4)',
          pointBackgroundColor: '#4CAF50',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesDataCompare(datasetArr, message);
    },
    renderChart2025AndRestCompare(){
      let message = `Сравнение продаж с остатками '${this.currentFindElementCompare}' в Епицентре за 2025 год.`
      let datasetArr = [
        {
          label: 'Продажи',
          data: this.single2025CountCompare,
          borderColor: '#FF4081',
          backgroundColor: 'rgba(255,64,129,0.4)',
          pointBackgroundColor: '#FF4081',
          tension: 0.3

        },
        {
          label: 'Остатки',
          data: this.single2025RestCompare,
          borderColor: '#4CAF50',
          backgroundColor: 'rgba(76,175,80,0.4)',
          pointBackgroundColor: '#4CAF50',
          tension: 0.3
        },
      ]
      this.showSingleElementSalesDataCompare(datasetArr, message);
    },

    showSingleElementSalesDataCompare(data, msg) {
      let datasets = data;

      if (this.isRenderingChartCompare) return;
      this.isRenderingChartCompare = true;

      this.destroyChartCompare();

      this.$nextTick(() => {
        this.createChartLineCompare(this.nameOfMonth, datasets, msg);

        setTimeout(() => {
          this.isRenderingChartCompare = false;
          this.isDisabled = false;
        }, 1000);
      });
    },
    createChartLineCompare(months, data, message) {
      let title = message;
      const canvas = this.$refs.itemChartCompare;
      if (!canvas) {
        console.warn('Canvas не найден');
        return;
      }
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        console.warn('Контекст canvas не получен');
        return;
      }

      this.chartCompare = new Chart(ctx, {
        type: 'line',
        data: {
          labels: months,
          datasets: data
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              position: 'top',
            },
            title: {
              display: true,
              text: title
            },
            datalabels: {
              display: false // ⛔️ отключает подписи данных
            }
          }
        },
      });
    },
  },
  mounted() {
    document.addEventListener('keydown', this.handleEnter);
    this.injectData();
  },
  beforeUnmount() {
    document.removeEventListener('keydown', this.handleEnter);
    this.destroyChart();
  },
  watch: {
    mainItemInput(newVal, oldVal) {
      if (newVal !== oldVal) {
        if (newVal !== null && newVal.trim() !== '') {
          this.isCompareInput = false;
        } else if (newVal === null || newVal.trim() === '') {
          this.compareItemInput = null;
          this.isCompareInput = true;
        }
      }
    },
  },
}
</script>

