<template>
  <div class="footer-data" ref="copyrights"></div>
</template>

<script>
export default {
  name: "FooterComponent",
  data() {
    return {};
  },
  methods: {
    createFooterData() {
      let date = new Date();
      let currentYear = 2025;
      if (date.toLocaleDateString().slice(6) == currentYear) {
        this.$refs.copyrights.textContent = `© TNP Analizer ${currentYear}`;
      } else {
        this.$refs.copyrights.textContent = `© TNP Analizer 2025 - ${date.toLocaleDateString().slice(6)}`;
      }
    }
  },
  mounted() {
    this.createFooterData();
  }
}
</script>

