<template>
  <div class="main-container">
    <div class="section-header">
      <TimeComponent/>
    </div>
    <div class="section-body">
      <div class="preloader" v-if="!bodyComponentIsShow">
        <v-progress-circular
            :size="70"
            :width="7"
            color="green"
            indeterminate
        ></v-progress-circular>
      </div>
      <body-component v-if="bodyComponentIsShow"/>
    </div>
    <div class="section-footer">
      <FooterComponent/>
    </div>
    <div class="box-element">
      <div class="box-element__text">Analyzer</div>
    </div>
  </div>
</template>

<script>
import $ from 'jquery';
import Swal from 'sweetalert2';
import {DataStorage} from "@/functions/data-storage";
import TimeComponent from './components/TimeComponent.vue';
import FooterComponent from "@/components/FooterComponent.vue";
import BodyComponent from "@/components/BodyComponent.vue";

export default {
  name: 'App',
  components: {
    BodyComponent,
    FooterComponent,
    TimeComponent
  },
  data() {
    return {
      bodyComponentIsShow: false,
      isLoaded: {
        sales: false,
        reserves: false,
      },
      storage: DataStorage
    }
  },
  methods: {
    async getDataRequest() {
      await $.ajax({
        url: 'https://script.google.com/macros/s/AKfycbxH2zxGqqz-NMzE1PU7M8AA6ZdASLqeWzDXwjedVMmjw1eru5Ue81CTOL2ch4_ff1CZ/exec',
        type: "GET",
        crossDomain: true,
        dataType: "json",
        success: (response) => {
          this.fillStorage(response.sales);
        },
        error: () => {
          const Toast = Swal.mixin({
            toast: true,
            position: "top-end",
            showConfirmButton: false,
            timer: 2000,
            timerProgressBar: true,
            didOpen: (toast) => {
              toast.onmouseenter = Swal.stopTimer;
              toast.onmouseleave = Swal.resumeTimer;
            }
          });
          Toast.fire({
            icon: "error",
            title: "Ошибка загрузки данных"
          }).then(() => {
            location.reload();
          });
        }
      });
      await $.ajax({
        url: 'https://script.google.com/macros/s/AKfycbycgFWyXe4mp_hb5jg48ak4eTcTp3yoUf_IMe_j9NZ84QAJq0KFccakkj3QHySyg07uMQ/exec',
        type: "GET",
        crossDomain: true,
        dataType: "json",
        success: (response) => {
          this.storage.prototype.fullReserves = response.reservs;
          this.isLoaded.reserves = true;
        },
        error: () => {
          const Toast = Swal.mixin({
            toast: true,
            position: "top-end",
            showConfirmButton: false,
            timer: 2000,
            timerProgressBar: true,
            didOpen: (toast) => {
              toast.onmouseenter = Swal.stopTimer;
              toast.onmouseleave = Swal.resumeTimer;
            }
          });
          Toast.fire({
            icon: "error",
            title: "Ошибка загрузки данных"
          }).then(() => {
            location.reload();
          });
        }
      });
    },

    fillStorage(response) {
      let categoryArray = [];
      let years = ['2023', '2024', '2025'];
      let months = [
        'январь',
        'февраль',
        'март',
        'апрель',
        'май',
        'июнь',
        'июль',
        'август',
        'сентябрь',
        'октябрь',
        'ноябрь',
        'декабрь'
      ];

      this.storage.prototype.fullData = response;
      this.storage.prototype.fullData2023 = response.filter(item => item.year === '2023');
      this.storage.prototype.fullData2024 = response.filter(item => item.year === '2024');
      this.storage.prototype.fullData2025 = response.filter(item => item.year === '2025');

      response.forEach(item => {
        categoryArray.push(item.category)
      });
      this.storage.prototype.categoryNames = [...new Set(categoryArray)].sort((a, b) => a.localeCompare(b));

      this.storage.prototype.yearsNames = years;
      this.storage.prototype.monthNames = months;
      this.isLoaded.sales = true;
    }
  },
  created() {
    this.getDataRequest();
  },
  watch: {
    isLoaded: {
      handler(newValue) {
        if (newValue.sales && newValue.reserves) {
          this.bodyComponentIsShow = true;
        }
      },
      deep: true
    }
  }
}
</script>

