export class DataStorage {
    constructor() {
        this._fullData = [];
        this._fullData2023 = [];
        this._fullData2024 = [];
        this._fullData2025 = [];
        this._fullReserves = [];
        this._yearsNames = [];
        this._monthNames = [];
        this._categoryNames = [];
    }

    // Getters
    get fullData() {
        return this._fullData;
    }

    get fullData2023() {
        return this._fullData2023;
    }

    get fullData2024() {
        return this._fullData2024;
    }

    get fullData2025() {
        return this._fullData2025;
    }

    get fullReserves() {
        return this._fullReserves;
    }

    get monthNames() {
        return this._monthNames;
    }

    get yearsNames() {
        return this._yearsNames;
    }

    get categoryNames() {
        return this._categoryNames;
    }

    // Setters
    set fullData(data) {
        this._fullData = [...data];
    }

    set fullData2023(data) {
        this._fullData2023 = [...data];
    }

    set fullData2024(data) {
        this._fullData2024 = [...data];
    }

    set fullData2025(data) {
        this._fullData2025 = [...data];
    }

    set fullReserves(reserves) {
        this._fullReserves = [...reserves];
    }

    set monthNames(months) {
        this._monthNames = [...months];
    }

    set yearsNames(years) {
        this._yearsNames = [...years];
    }

    set categoryNames(categories) {
        this._categoryNames = [...categories];
    }
}