<template>
  <div class="main-chart-container">
    <canvas ref="mainChart" class="main-chart"></canvas>
  </div>
  <div class="controls">
    <v-btn
        size="small"
        color="teal"
        class="controls_btn"
        :disabled="isDisabled"
        @click="salesChart"
    >
      Общая динамика
    </v-btn>
    <div class="controls_category">
      <v-btn
          size="small"
          color="teal"
          class="controls_btn"
          :disabled="isDisabled"
          @click="categoryCart"
      >
        Категории
      </v-btn>
      <v-select
          label="Категории"
          :items="nameOfCategory.sort((a, b) => a.localeCompare(b))"
          variant="underlined"
          density="comfortable"
          color="teal"
          clearable
          hide-details
          v-model="chooseCategory"
      ></v-select>
      <v-btn
          size="small"
          color="teal"
          class="controls_btn"
          :disabled="isDisabled"
          @click="getchoosedCategory"
      >
        Выбрать
      </v-btn>
    </div>
  </div>
</template>

<script>
import {DataStorage} from "@/functions/data-storage";
import {Chart, registerables} from 'chart.js';
import ChartDataLabels from 'chartjs-plugin-datalabels';

Chart.register(...registerables, ChartDataLabels);

export default {
  name: "MainSalesChart",
  data() {
    return {
      chart: null,
      storage: DataStorage,

      fullSales: [],
      fullSales2023: [],
      fullSales2024: [],
      fullSales2025: [],

      nameOfMonth: [],
      nameOfCategory: [],
      moneyOfCategory: [],
      categoryNamesAndSums: [],

      chooseCategory: null,
      isDisabled: false,
      isRenderingChart: false,
    };
  },
  methods: {
    injectData() {
      this.fullSales = [...this.storage.prototype.fullData];
      this.fullSales2023 = [...this.storage.prototype.fullData2023];
      this.fullSales2024 = [...this.storage.prototype.fullData2024];
      this.fullSales2025 = [...this.storage.prototype.fullData2025];
      this.nameOfMonth = [...this.storage.prototype.monthNames];

      this.nameOfCategory = [...this.storage.prototype.categoryNames];
    },
    destroyChart() {
      if (this.chart) {
        this.chart.destroy();
        this.chart = null;
      }
    },

    categoryCart() {
      this.isDisabled = true;
      this.getCategorySalesData();
    },
    getCategorySalesData() {
      // Новый массив с объектами: { category: '...', money: ... }
      this.categoryNamesAndSums = this.nameOfCategory.map(cat => {
        const sum = this.fullSales
            .filter(item => item.category === cat)
            .reduce((acc, item) => acc + item.money, 0);

        return {
          category: cat,
          money: Number(sum.toFixed(0))
        };
      });

      this.categoryNamesAndSums.sort((a, b) => b.money - a.money);
      this.nameOfCategory = this.categoryNamesAndSums.map(obj => obj.category);
      this.moneyOfCategory = this.categoryNamesAndSums.map(obj => obj.money);

      let message = `Сумарные продажи в разрезе категорий за период 2023-2025`;
      this.showCategorySalesData(message);
    },
    showCategorySalesData(msg) {
      if (this.isRenderingChart) return;
      this.isRenderingChart = true;

      this.destroyChart();

      this.$nextTick(() => {
        this.createChartBar(this.nameOfCategory, this.moneyOfCategory, msg, '#00897B', '#4DB6AC', 'грн');

        setTimeout(() => {
          this.isRenderingChart = false;
          this.isDisabled = false;
        }, 1000);
      });
    },

    salesChart() {
      this.isDisabled = true;
      this.getFullYearsSalesData();
    },
    getFullYearsSalesData() {
      let year2023 = [];
      let year2024 = [];
      let year2025 = [];

      this.nameOfMonth.map(month => {
        const sum = this.fullSales2023
            .filter(item => item.month === month)
            .reduce((acc, item) => acc + item.money, 0);

        if (sum === 0) {
          year2023.push({
            month: month,
            money: null
          })
        } else {
          year2023.push({
            month: month,
            money: Number(sum.toFixed(0))
          })
        }
      });
      this.nameOfMonth.map(month => {
        const sum = this.fullSales2024
            .filter(item => item.month === month)
            .reduce((acc, item) => acc + item.money, 0);

        if (sum === 0) {
          year2024.push({
            month: month,
            money: null
          })
        } else {
          year2024.push({
            month: month,
            money: Number(sum.toFixed(0))
          })
        }
      });
      this.nameOfMonth.map(month => {
        const sum = this.fullSales2025
            .filter(item => item.month === month)
            .reduce((acc, item) => acc + item.money, 0);

        if (sum === 0) {
          year2025.push({
            month: month,
            money: null
          })
        } else {
          year2025.push({
            month: month,
            money: Number(sum.toFixed(0))
          })
        }
      });

      let year2023sales = year2023.map(item => item.money);
      let year2024sales = year2024.map(item => item.money);
      let year2025sales = year2025.map(item => item.money);

      let message = `Динамика продаж в Епицентре за 2023, 2024, 2025 гг.`
      this.showFullYearsSalesData(year2023sales, year2024sales, year2025sales, message);
    },
    showFullYearsSalesData(data2023, data2024, data2025, msg) {
      if (this.isRenderingChart) return;
      this.isRenderingChart = true;

      this.destroyChart();

      this.$nextTick(() => {
        this.createChartLine(this.nameOfMonth, data2023, data2024, data2025, msg);

        setTimeout(() => {
          this.isRenderingChart = false;
          this.isDisabled = false;
        }, 1000);
      });
    },

    getchoosedCategory() {
      if (this.chooseCategory) {
        let year2023 = [];
        let year2024 = [];
        let year2025 = [];

        this.nameOfMonth.map(month => {
          const sum = this.fullSales2023
              .filter(item => item.month === month && item.category === this.chooseCategory)
              .reduce((acc, item) => acc + item.money, 0);

          if (sum === 0) {
            year2023.push({
              month: month,
              money: null
            })
          } else {
            year2023.push({
              month: month,
              money: Number(sum.toFixed(0))
            })
          }
        });
        this.nameOfMonth.map(month => {
          const sum = this.fullSales2024
              .filter(item => item.month === month && item.category === this.chooseCategory)
              .reduce((acc, item) => acc + item.money, 0);

          if (sum === 0) {
            year2024.push({
              month: month,
              money: null
            })
          } else {
            year2024.push({
              month: month,
              money: Number(sum.toFixed(0))
            })
          }
        });
        this.nameOfMonth.map(month => {
          const sum = this.fullSales2025
              .filter(item => item.month === month && item.category === this.chooseCategory)
              .reduce((acc, item) => acc + item.money, 0);

          if (sum === 0) {
            year2025.push({
              month: month,
              money: null
            })
          } else {
            year2025.push({
              month: month,
              money: Number(sum.toFixed(0))
            })
          }
        });

        let year2023sales = year2023.map(item => item.money);
        let year2024sales = year2024.map(item => item.money);
        let year2025sales = year2025.map(item => item.money);

        let message = `Динамика продаж в Епицентре за 2023, 2024, 2025 гг. в категории '${this.chooseCategory}'`
        this.showFullYearsSalesData(year2023sales, year2024sales, year2025sales, message);
      }
    },

    createChartBar(data, count, message, colorUp, colorDown, chartTitle) {
      let title = chartTitle;
      const canvas = this.$refs.mainChart;
      if (!canvas) {
        console.warn('Canvas не найден');
        return;
      }
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        console.warn('Контекст canvas не получен');
        return;
      }
      const gradient = ctx.createLinearGradient(0, 0, 0, 400); // Вертикальный градиент
      gradient.addColorStop(0, colorUp); // Цвет в начале
      gradient.addColorStop(1, colorDown); // Цвет в конце

      this.chart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: data,
          datasets: [{
            label: title,
            data: count,
            backgroundColor: gradient,
            borderWidth: 1
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: false,
            subtitle: {
              display: true,
              text: message,
              font: {
                weight: 'bold',
                size: '13',
              },
              padding: {
                top: 5,
                bottom: 35, // Отступ снизу текста
              }
            },
            datalabels: {
              display: false,
              color: '#00897B', // Цвет текста
              anchor: 'end', // Расположение метки
              align: 'top', // Выравнивание метки
              rotation: -90,
              formatter: (value) => value !== 0 ? value.toLocaleString() : ''
            }
          },
          scales: {
            y: {
              beginAtZero: true,
            },
            x: {}
          }
        },
      });
    },
    createChartLine(months, data2023, data2024, data2025, message) {
      let title = message;
      const canvas = this.$refs.mainChart;
      if (!canvas) {
        console.warn('Canvas не найден');
        return;
      }
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        console.warn('Контекст canvas не получен');
        return;
      }

      this.chart = new Chart(ctx, {
        type: 'line',
        data: {
          labels: months,
          datasets: [
            {
              label: '2023',
              data: data2023,
              borderColor: '#2196F3',
              backgroundColor: 'rgba(33,150,243,0.4)',
              pointBackgroundColor: '#2196F3',
              tension: 0.3
            },
            {
              label: '2024',
              data: data2024,
              borderColor: '#FF4081',
              backgroundColor: 'rgba(255,64,129,0.4)',
              pointBackgroundColor: '#FF4081',
              tension: 0.3
            },
            {
              label: '2025',
              data: data2025,
              borderColor: '#FF9100',
              backgroundColor: 'rgba(255,145,0,0.4)',
              pointBackgroundColor: '#FF9100',
              tension: 0.3
            },
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              position: 'top',
            },
            title: {
              display: true,
              text: title
            },
            datalabels: {
              display: false // ⛔️ отключает подписи данных
            }
          }
        },
      });
    },
  },
  mounted() {
    this.injectData();
    this.salesChart();
  },
  beforeUnmount() {
    this.destroyChart();
  },
  watch: {}
}
</script>

<style lang="scss" scoped>
.main-chart-container {
  width: 100%;
  max-height: 500px;

  .main-chart {
    width: 100%;
    height: 100%;
  }
}

.controls {
  width: 100%;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;

  .controls_category {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    gap: 10px;
    width: 400px;
  }
}
</style>